"""Consolidated entry point; does not mutate archived research editions."""
from pathlib import Path
from html import escape as e
import json
ROOT = Path(__file__).resolve().parents[1]
SOURCES = {
 'SAFE': ('SAFE individual FX measures, Articles 7, 13, 26, 28, 37', 'https://www.safe.gov.cn/safe/2006/1225/5319.html'),
 'AMEND': ('SAFE 2014 No. 2, Section VI (amended republication)', 'https://www.safe.gov.cn/tianjin/2024/0903/2594.html'),
 'IRS': ('IRS: U.S. citizens and resident aliens abroad, opening and reporting sections', 'https://www.irs.gov/individuals/international-taxpayers/us-citizens-and-resident-aliens-abroad'),
 'BOC': ('BOC personal electronic-banking tariff, cross-border TT and note 1', 'https://www.boc.cn/ebanking/service/cs1/200905/t20090506_990712.html'),
 'WISE': ('Wise: Guide to CNY transfers, Sending from CNY section', 'https://wise.com/help/articles/2955298/guide-to-cny-transfers'),
 'DIV': ('MOF/STA 2026 No. 27, Sections I–III', 'https://shanghai.chinatax.gov.cn/zzzb/zcwj/202609/t481448.html'),
}
FINDINGS = [
 ('Start with documented income, if that is the real source', 'SAFE Article 13 permits overseas individuals to purchase and remit lawful current-account RMB income with identity and supporting evidence. Citizenship alone does not prove that this balance qualifies.', ['SAFE']),
 ('Separate capital transfers from earned income', 'For pre-emigration property or inheritance, use the applicable approval route. Section VI removed mandatory staged emigrant releases; approved amounts can be remitted once or in installments. Eligibility and tax evidence still matter.', ['SAFE','AMEND']),
 ('There is no verified personal conversion-tax figure', 'U.S. citizens are taxed on worldwide income. A wire fee is not an income tax. Prior tax, foreign tax credits, currency gains and reporting depend on facts not supplied; do not treat the old $0 headline as advice.', ['IRS']),
 ('Compare execution rails only after confirming eligibility', 'BOC publishes commission and cable charges; local pricing and discounts may differ. Wise is restricted to eligible workers/former workers with qualifying China tax records and an account they own abroad.', ['BOC','WISE']),
 ('Keep reporting separate from transfer cost', 'Foreign accounts may require FBAR even without taxable income. Certain foreign gifts, bequests and trust transactions require Form 3520. Moving the money does not erase historical reporting duties.', ['IRS']),
 ('Do not split quotas or fabricate transactions', 'SAFE Article 7 prohibits splitting to evade limit supervision and false commercial documents. No operational steps are supplied for prohibited schemes.', ['SAFE']),
]
CSS='''*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#182632;font:16px/1.65 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:24px 18px 60px}a{color:#076658}a:focus-visible{outline:3px solid #ad7800}nav{display:flex;gap:18px;flex-wrap:wrap;border-bottom:1px solid #d5dee5;padding-bottom:16px}h1{font-size:clamp(2rem,5vw,3.4rem);line-height:1.12;max-width:24ch}h2{margin-top:36px}.muted,small{color:#526371}.lead{max-width:76ch;font-size:1.12rem}.notice{border-left:4px solid #b67a10;background:#fff5df;padding:16px 20px;margin:24px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.card{padding:20px;background:white;border:1px solid #d5dee5;border-radius:12px;text-decoration:none;color:inherit}.card strong{color:#076658;font-size:1.1rem}.card p{margin:8px 0 0}.scroll{overflow:auto;background:white;border:1px solid #d5dee5;border-radius:10px}table{border-collapse:collapse;width:100%;font-size:.92rem}th,td{padding:12px;text-align:left;border-bottom:1px solid #e0e6eb;vertical-align:top}th{background:#eaf1f3}caption{text-align:left;padding:14px;font-weight:650}.source{display:inline-block;margin:2px 8px 2px 0;white-space:nowrap}.blank{min-width:65px;background:#fffaf0}footer{margin-top:32px;border-top:1px solid #d5dee5;padding-top:16px}.pill{display:inline-block;padding:4px 10px;background:#e0eee9;color:#225747;border-radius:20px}@media(max-width:600px){.responsive thead{display:none}.responsive tr{display:block;border-bottom:2px solid #d5dee5}.responsive td{display:block}.responsive td:first-child{font-weight:bold;background:#eaf1f3}.costs{font-size:.79rem}.costs td,.costs th{padding:9px 6px}}'''
def links(ids):
 return ''.join(f'<a class="source" href="{SOURCES[i][1]}" title="{e(SOURCES[i][0])}" rel="noopener noreferrer">{i} ↗</a>' for i in ids)
def table(headers, rows, responsive=True):
 return '<div class="scroll"><table class="'+('responsive' if responsive else 'costs')+'"><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def shell(title, body, sub=False):
 p='../' if sub else ''
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Evidence-qualified CNY to USD transfer research for a US citizen. Legal routes, cost grids and verification gaps."><title>{e(title)} · China Money</title><style>{CSS}</style></head><body><main><nav aria-label="Main navigation"><strong>China Money</strong><a href="{p}index.html">Overview</a><a href="{p}edition-g/docs/costs.html">Costs</a><a href="{p}edition-g/docs/category-personal.html">Methods</a><a href="{p}integration/review.html">Flagged for Review</a><a href="{p}integration/evidence.html">Evidence log</a></nav>{body}<footer><p>Research, not legal or tax advice. Unknown is not zero. No bank account, tax record or executable quote was supplied. Official agencies support rules; provider-primary sources support only their own terms.</p><a href="{p}COORDINATION.md">Coordination and publication record</a> · Integration date: 9 November 2026 (UTC).</footer></main></body></html>'''
def build():
 cards=[('edition-g/docs/category-personal.html','Personal legal routes','Documented income, emigrant property, inheritance and other conditional entitlements.'),('edition-g/docs/costs.html','Cost comparison','43 candidates × 40 targets. Published components only; unknown totals blank.'),('edition-g/docs/category-rails.html','Banks and payment providers','Compare execution rails, eligibility, fees, pros and cons.'),('edition-g/docs/category-business.html','Business and asset routes','Genuine distributions and asset transactions; not ways to relabel savings.'),('edition-g/docs/taxes.html','Tax and reporting','Separate underlying taxes, FX gains and filing penalties.'),('integration/review.html','Flagged for Review','Material conflicts and unverified personal values; archives remain accessible.'),('edition-g/docs/repo-review.html','Repository audit','Prior edition line-scan inventory and targeted irregularity review.'),('edition-g/docs/sources.html','Full source register','Inherited register of government and provider-primary evidence.'),('edition-g/docs/category-rejected.html','Rejected and unavailable routes','Prohibited schemes and unsupported corridors are not recommendations.')]
 # Validate destinations before publication; no silent broken navigation.
 for href,_,_ in cards:
  if href.startswith('edition-'): assert (ROOT/href).is_file(), href
 body='''<p class="pill">Consolidated research · no personal data entry required</p><h1>A lawful route first.<br>A price comparison second.</h1><p class="lead">For a U.S. citizen with CNY in a Chinese bank, the first question is <strong>how the money was earned and documented</strong>, not which app advertises the lowest fee. Start with the documented-income bank route if eligible; otherwise investigate the matching property, inheritance or business route.</p><div class="notice"><strong>Executive summary:</strong> No single cheapest route or exact tax penalty can be established from the facts supplied. Earlier editions displayed exact all-in totals and a blanket $0 tax claim. Those are not verified personal quotes and are no longer the landing-page recommendation. Unconfirmed amounts stay blank.</div><div class="cards">'''+''.join(f'<a class="card" href="{h}"><strong>{e(t)} →</strong><p>{e(d)}</p></a>' for h,t,d in cards)+'</div><h2>The decision in six rows</h2>'+table(['Priority','What the evidence supports','Primary source'],[[e(t),e(d),links(s)] for t,d,s in FINDINGS])
 body+='''<h2>Cost ladder: $10,000 to $400,000</h2><p>The compact ladder below shows the <strong>published BOC sender tariff bounds</strong>, not a personalized cost estimate: 0.1% commission, minimum CNY 50 and maximum CNY 260, plus CNY 150 cable for non-Hong-Kong/Macau/Taiwan destinations. This is the published electronic-banking base schedule; note 1 permits agreements, discounts and local variations. Availability for this user's documented route is unverified.</p><p><strong>CNY 200–410 is a tariff envelope per transfer, not the actual fee at every amount.</strong> No CNY/USD conversion rate is assumed. Multiple transfers can incur multiple fees. Blank cells below are UNVERIFIED, not free. FX, intermediaries, receiver, documentation and tax remain outside this envelope.</p>'''
 rows=[]
 for n in range(10000,400001,10000):
  rows.append([f'${n:,}','CNY 200–410','<span aria-label="Unverified tax"></span>','<span aria-label="Unverified all-in total"></span>',links(['BOC','IRS'])])
 body+=table(['USD target¹','Sender bounds²','Tax³','All-in³','Source'],rows,False)
 body+='''<p class="muted">¹ Nominal USD comparison target, not guaranteed net receipt. ² One qualifying transfer, published base schedule only. ³ Blank = UNVERIFIED. <a href="edition-g/docs/costs.html">All 1,720 candidate/target rows and component breakdowns →</a></p><h2>Practical next steps — conditional, not an execution guarantee</h2><ol><li>Classify each portion of the balance by its true source; retain the bank trail.</li><li>Have the bank confirm FX identity classification and the applicable route. Article 13 supports documented lawful current income of an overseas individual; other sources require their own rules.</li><li>Gather identity, source and applicable tax evidence. For an emigrant or inheritance route, obtain the competent SAFE approval and current checklist.</li><li>Compare an executable bank quote with an eligible provider quote for the same USD outcome, at the same time. Include FX, sender, cable, intermediary and receiving charges.</li><li>Execute only after approval. Retain conversion slips, remittance receipts and tax records; reconcile U.S. income and foreign-account reporting.</li></ol><p>Basis: '''+links(['SAFE','AMEND','BOC','WISE','IRS'])+'''</p><h2>Preserved research archive</h2><p>These editions can disagree. Inclusion is not re-certification; read the review flags before relying on numerical examples.</p><ul>'''
 for href,title in [('pages/estimates.html','Original USD scenario table'),('overview.html','Original overview'),('docs/index.html','Supplemental dashboard'),('dossier/index.html','Dossier'),('edition-b/index.html','Edition B'),('edition-c/docs/index.html','Edition C'),('edition-d/docs/index.html','Edition D — historical scenario model'),('edition-e/docs/index.html','Edition E'),('edition-f/site/index.html','Edition F'),('edition-g/docs/index.html','Edition G — broadest existing candidate catalog')]:
  # Edition E uses site, check below when building.
  if not (ROOT/href).is_file() and title=='Edition E': href='edition-e/site/index.html'
  assert (ROOT/href).is_file(),href
  body+=f'<li><a href="{href}">{e(title)}</a></li>'
 body+='</ul>'
 (ROOT/'index.html').write_text(shell('Overview',body),encoding='utf-8')
 flags=[
 ('I01 · Removed universal price claim','Root landing previously claimed costs under 1% at all sizes and exact totals ($83.45 at $10,000; $932.72 at $400,000). These are scenario arithmetic, not a verified quote. A bid/ask gap does not establish one-way customer loss; an assumed recipient fee does not establish this account’s fee. Archived Edition D remains unchanged.', ['BOC']),
 ('I02 · Removed blanket $0 conversion tax','U.S. worldwide-income and currency-gain analysis cannot be replaced with a universal tax-free statement. Unknown basis, income history, residence and compliance history prevent personal tax calculation.', ['IRS']),
 ('I03 · Identity is necessary, not sufficient','A passport alone is not a right to export any balance. Article 13 requires lawful current-account income with supporting documents; capital property has separate rules.', ['SAFE']),
 ('I04 · Old staged emigrant rules','Section VI of the 2014 amendment cancels mandatory staged emigrant remittances. Do not rely on the original 2004 staging schedule without this amendment.', ['AMEND']),
 ('I05 · Recent dividend rule','Rechecked official Shanghai STA page: MOF/STA 2026 No. 27 states 20% IIT for foreign individuals’ FIE dividends effective 1 September 2026 and repeals the specified 1994 exemption. Earlier exemption claims are stale. Individual treaty effects and applicability remain case-specific.', ['DIV']),
 ('I06 · Provider eligibility and limits','Wise requires qualifying work history and tax records; own-account destination; CNY 300,000 per bank-app transfer or CNY 50,000 via Alipay, plus overall after-tax-income limit. It is not an unrestricted route for accumulated savings.', ['WISE']),
 ('I07 · Missing user facts','Bank, account holder classification, source dates, tax status, CNY balance, USD basis and recipient fees are unknown. No account-specific total, tax amount, net USD or best provider is certified.', ['SAFE','IRS','BOC']),
 ('I08 · Verification limits','This integration directly re-read six primary-source pages and reviewed root claims. Prior catalog citations and audit records are inherited, not a new line-by-line legal re-certification. Mechanical row/link checks cannot prove every legal proposition or future source availability.', ['SAFE','IRS']),
 ]
 review='<h1>Flagged for Review</h1><p class="lead">Non-blocking evidence gaps and material corrections. Archived content is preserved for traceability, not endorsed as current advice.</p>'+table(['Flag','Finding / disposition','Primary source'],[[e(a),e(b),links(c)] for a,b,c in flags])+'<h2>Detailed inherited flags</h2><p><a href="../edition-g/docs/flagged.html">Edition G flags</a> · <a href="../edition-f/site/flagged.html">Edition F flags</a> · <a href="../edition-d/docs/pages/flagged.html">Edition D flags</a></p>'
 (ROOT/'integration/review.html').write_text(shell('Flagged for Review',review,True),encoding='utf-8')
 evidence='<h1>Evidence and verification log</h1><p>Directly retrieved using the page-retrieval tool on 9 November 2026 UTC. Scope below is what was actually inspected, not a claim of exhaustive legal review. Government sources establish rules; BOC and Wise are provider-primary only.</p>'+table(['ID / classification','Inspected scope','Primary source'],[[e(i)+' · '+('provider-primary' if i in ['BOC','WISE'] else 'government'),e(t),links([i])] for i,(t,u) in SOURCES.items()])+'<p>IRS and Wise: opening / relevant sections in chunk 0 only; later unrelated chunks were not needed for these claims. The other four pages were returned completely.</p><h2>Requirement coverage</h2><ul><li>Executive summary: consolidated landing page.</li><li>Methods, pros/cons and steps: linked Edition G category and individual-method pages.</li><li>All USD targets: 40-row compact ladder and inherited 43 × 40 candidate grids.</li><li>Unknown personal costs: blank and flagged, never invented.</li><li>Repo review: inherited line inventory and targeted findings, plus this root-claim review.</li><li>Deployment: GitHub PR/checks/Pages result recorded in COORDINATION.md.</li></ul><p><strong>Not completed as a factual claim:</strong> an exact personal all-in estimate for every method, or independent legal verification of every inherited line. Neither is established by the available facts. No user credentials or manual inputs requested.</p>'
 (ROOT/'integration/evidence.html').write_text(shell('Evidence log',evidence,True),encoding='utf-8')
 (ROOT/'integration/evidence.json').write_text(json.dumps({'checked_utc':'2026-11-09','method':'Direct fetch_page relevant text inspection','sources':SOURCES,'flags':flags},indent=2)+'\n')
if __name__=='__main__': build()
